  const int32_t r = blockIdx.x;
  if (r >= queries) return;
  const int64_t base = int64_t(r) * keys;
  // The state token's heads see only the prefix; the action tokens see all.
  const bool all_keys = (r >= heads);

  float held[kMaxPerThread];
  int32_t n = 0;
