    const float value = __bfloat162float(x[row * 1024 + col]);
    sum += value * value;
    scaled[row * 1024 + col] =
        __float2bfloat16_rn(value * __bfloat162float(scale[col]));
  }
#pragma unroll
  for (int32_t offset = 16; offset > 0; offset >>= 1)
    sum += __shfl_down_sync(0xffffffffu, sum, offset);
